// Analysis is everything a renderer needs. It is built once and handed to
// every output format, so the table, the JSON, the HTML and the packet can
// never disagree with each other.
type Analysis struct {
	Version string

	CheckpointID string
	Commit       string
	Parent       string
	Agent        string
	Adapter      string
	Route        string
	SessionIDs   []string
