func TestNoteUnnamedCarriesTheCountOntoTheReport(t *testing.T) {
	a := &report.Analysis{}
	// 51 counted, 20 named, which is the shape of a capped verify list.
	v := graph.Verdict{FailingCount: 51, NewlyFailing: make([]string, 20)}
	noteUnnamed(a, v)
