	SortDocket(nodes)

	byName := map[string]*Node{}
	for _, n := range nodes {
		byName[n.Symbol.Name] = n
	}
	return scenarioResult{
		nodes: nodes, byName: byName, summary: Summarize(nodes),
		field: field, relMap: relMap, sources: sources, srcIDs: []string{src.ID},
	}
}

